mapper.sql:
SELECT p.id, p.user_id AS userId, 'post' AS boardType, p.post_type AS postType, NULL AS courseKind, p.title, p.views, p.created_at AS createdAt, u.nickname, , COALESCE(postComments.commentCount, 0) AS commentCount, COALESCE(postBookmarks.bookmarkCount, 0) AS bookmarkCount FROM user_posts p JOIN users u ON u.id = p.user_id
WHERE p.deleted = 0
AND p.post_type = #{postType}

